import sys
import time
import queue

class Node:
	__slots__ = ['is_leaf', 'value', 'left', 'right', 'mid', 'count']

	def __str__(self):
		return 'value: ' + self.value + ', mid: ' + str(self.mid) + ', left: ' + str(self.left) + ', right: ' + str(self.right)

	def __init__(self):
		self.is_leaf = False
		self.value = None
		self.left = None
		self.right = None
		self.mid = None
		self.count = 0

	def insert(self, word):
		if len(word) == 0:
			return
		if self.value is None:
			self.count = self.count + 1
			self.value = word[0]
			if len(word) == 1:
				self.is_leaf = True
			else:
				if self.mid is None:
					self.mid = Node()
				self.mid.insert(word[1:])
		elif self.value == word[0]:
			self.count = self.count + 1
			if self.mid is None:
				self.mid = Node()
			self.mid.insert(word[1:])
		elif self.value > word[0]:
			if self.left is None:
				self.left = Node()
			self.left.insert(word)
		else:
			if self.right is None:
				self.right = Node()
			self.right.insert(word)

	def words(self):
		words = 0
		nodes_to_check = queue.Queue()
		nodes_to_check.put((self, ''))
		while not nodes_to_check.empty():
			node_prefix = nodes_to_check.get()
			curr_node = node_prefix[0]
			curr_prefix = node_prefix[1]
			if curr_node.value is not None:
				curr_prefix = curr_prefix + curr_node.value
			if curr_node.is_leaf:
				words = words + 1
			if curr_node.mid is not None:
				nodes_to_check.put((curr_node.mid, curr_prefix))
			if curr_node.left is not None:
				nodes_to_check.put((curr_node.left, node_prefix[1]))
			if curr_node.right is not None:
				nodes_to_check.put((curr_node.right, node_prefix[1]))
		return words

	def start_with(self, word):
		parent = None
		root = self
		for char in word:
			if root is None:
				parent = None
			else:
				while root is not None and root.value is not None and (char != root.value):
					if char < root.value:
						root = root.left
					else:
						root = root.right
				if root is not None and char == root.value:
					parent = root
					root = root.mid
				else:
					parent = None
		if parent is None:
			return 0
		else:
			return parent.count
